"""A visual contact sheet and focused selection workspace."""
from pathlib import Path
from html import escape
from hashlib import sha256
import json,re
ROOT=Path(__file__).resolve().parent;SITE=ROOT.parent
GROUPS={'10':'app','14':'app','15':'app','04':'shop'}
def item(t):
 name=t['name'].split(' · ')[0]
 preview='/design/'+t['preview']+'?v='+sha256((ROOT/t['preview']).read_bytes()).hexdigest()[:10]
 return dict(slug=t['slug'],name=name,category=t['category'],summary=t['summary'],features=t['features'],use=t['use'],image=preview,demo='/design/'+t['file'],context='/design/'+t['slug']+'/',zip='/design/'+t['slug']+'/source.zip',group=GROUPS.get(t['id'],'story'),size=round(t['archive_bytes']/1024))
def library(catalog):
 items=[item(t) for t in sorted(catalog,key=lambda t:({'10':0,'11':1}.get(t['id'],2),catalog.index(t)))];first=items[0]
 rows=[]
 for i,t in enumerate(items):
  on=t['slug']==first['slug']
  rows.append(f'''<button type="button" class="design-row" data-template="{t['slug']}" aria-pressed="{str(on).lower()}"><img src="{t['image']}" width="1400" height="946" loading="{'eager' if i<2 else 'lazy'}" decoding="async" alt=""><span><strong>{escape(t['name'])}</strong><small>{escape(t['category'])}</small><span class="row-summary">{escape(t['summary'])}</span></span><span class="row-check" aria-hidden="true">{'✓' if on else '→'}</span></button>''')
 fallback=''.join(f'<li><a href="{t["demo"]}">{escape(t["name"])} saytini ochish ↗</a> · <a href="{t["context"]}">AI yo‘riqnomasi</a></li>' for t in items)
 data=json.dumps(items,ensure_ascii=False).replace('<','\\u003c')
 return f'''<section class="library" id="designs" data-view="list"><div class="library-heading"><div><p class="eyebrow">TANLOV UCHUN ISH MAYDONI</p><h1>Dizayn kutubxonasi<span>{len(items):02}</span></h1><p>Mos namuna tanlang. Ko‘ring, ishlating va topshiriqqa moslang.</p></div><a href="/design/start/" class="button dark">AIga topshiriq tayyorlash <span aria-hidden="true">↗</span></a></div><div class="library-toolbar"><label class="search"><span class="search-icon" aria-hidden="true">⌕</span><input id="design-search" type="search" placeholder="Dizayn yoki yo‘nalishni qidiring" aria-label="Dizayn qidirish"><kbd aria-hidden="true">/</kbd></label><div class="library-filters" role="group" aria-label="Dizayn yo‘nalishi"><button data-group="all" aria-pressed="true">Barchasi</button><button data-group="app" aria-pressed="false">Ilovalar</button><button data-group="story" aria-pressed="false">Hikoya va mazmun</button><button data-group="shop" aria-pressed="false">Savdo</button></div></div><div class="library-layout"><section class="design-index" aria-labelledby="index-title"><div class="index-heading"><h2 id="index-title">Dizaynni tanlang</h2><span id="design-count" role="status">{len(items)} ta dizayn</span></div><p class="index-hint">Kompozitsiyani solishtiring. Tanlangan namunada jonli sayt va kodni oching.</p><div id="design-rows">{''.join(rows)}</div></section><section class="selected-design" id="selected-design" aria-labelledby="selected-name"><div class="preview-browser"><div class="preview-bar"><span id="preview-address">{first['name']} · Sayt ko‘rinishi</span><a id="preview-expand" href="{first['demo']}" aria-label="Tanlangan saytni ochish">↗</a></div><a class="selected-image-link" id="preview-link" href="{first['demo']}" aria-label="{first['name']} saytini ochish"><img id="selected-image" src="{first['image']}" width="1400" height="946" alt="{first['name']} sahifasining ko‘rinishi" fetchpriority="high"></a></div><div class="selected-info"><div class="selected-heading"><div><p id="selected-category" class="eyebrow">{escape(first['category'])}</p><h2 id="selected-name" tabindex="-1">{escape(first['name'])}</h2></div><button type="button" class="mobile-back" id="back-to-list">← Barcha namunalar</button><a class="return-search" href="#design-search">Dizayn qidirish ↑</a></div><p id="selected-summary">{escape(first['summary'])}</p><div class="selected-actions"><span class="aurora-action"><a class="button dark" id="selected-demo" href="{first['demo']}">Saytni ochish <span aria-hidden="true">↗</span></a></span><a class="button outline" id="selected-start" href="/design/start/?design={first['slug']}" data-start>AI bilan boshlash <span aria-hidden="true">→</span></a></div><div class="selected-resources"><a id="selected-context" href="{first['context']}">AI yo‘riqnomasi ↗</a><a class="download-link" id="selected-download" href="{first['zip']}" download data-download>Kod ZIP yuklash <span id="selected-size">{first['size']} KB</span> ↓</a></div><div class="share-link"><button type="button" id="share-design">Tanlov havolasini nusxalash ↗</button><input id="share-url" aria-label="Tanlangan dizayn havolasi" readonly hidden><span id="share-status" role="status"></span></div><p class="download-status" id="download-status" role="status"></p><details class="use-details"><summary>Qaysi topshiriqqa mos?</summary><p id="selected-use">{escape(first['use'])}</p><p id="selected-features">{escape(first['features'])}</p></details><p class="selection-status" id="selection-status" role="status"></p></div></section><div class="no-results" id="search-empty" hidden><span aria-hidden="true">⌕</span><h2>Dizayn topilmadi</h2><p>Qidiruv so‘zini yoki yo‘nalishni o‘zgartiring.</p><button class="button outline" type="button" id="clear-search">Barchasini ko‘rsatish</button></div></div><noscript><section class="no-script"><h2>Jonli namunalar</h2><p>Tanlash paneli uchun JavaScript kerak. Quyidagi oddiy havolalar orqali saytlarni ochishingiz mumkin.</p><ul>{fallback}</ul></section></noscript><script type="application/json" id="library-data">{data}</script></section>'''

def frame(title,content,active='library'):
 for script,model in [('starter.mjs','starter-model.mjs'),('workspace.js','library-model.mjs')]:
  path=SITE/'assets/hq'/script;source=path.read_text(encoding='utf-8');version=sha256((SITE/'assets/hq'/model).read_bytes()).hexdigest()[:10]
  updated=re.sub(re.escape(model)+r'\?v=[^\']+',model+'?v='+version,source)
  if updated!=source:path.write_text(updated,encoding='utf-8',newline='\n')
 aurora=sha256((SITE/'assets/hq/aurora.css').read_bytes()).hexdigest()[:10]
 geometry=sha256((SITE/'assets/hq/geometry.css').read_bytes()).hexdigest()[:10]
 css=sha256((SITE/'assets/hq/workspace.css').read_bytes()).hexdigest()[:10];js=sha256((SITE/'assets/hq/site.js').read_bytes()).hexdigest()[:10]
 extra=''.join(f'<link rel="stylesheet" href="/assets/hq/{name}.css?v={sha256((SITE/("assets/hq/"+name+".css")).read_bytes()).hexdigest()[:10]}">' for name in (['exhibition'] if active=='library' else ['preparation'] if active=='preparation' else ['starter'] if active=='start' else []))
 if active=='start':extra+=f'<script type="module" src="/assets/hq/starter.mjs?v={sha256((SITE/"assets/hq/starter.mjs").read_bytes()).hexdigest()[:10]}"></script>'
 if active in ('architecture','api','workflow'):
  extra+=f'<link rel="stylesheet" href="/assets/hq/architecture.css?v={sha256((SITE/"assets/hq/architecture.css").read_bytes()).hexdigest()[:10]}">'
 if active=='architecture':extra+=f'<script type="module" src="/assets/hq/architecture.mjs?v={sha256((SITE/"assets/hq/architecture.mjs").read_bytes()).hexdigest()[:10]}"></script>'
 module=sha256((SITE/'assets/hq/workspace.js').read_bytes()).hexdigest()[:10]
 nav=[('library','/','▦','Dizayn kutubxonasi'),('preparation','/tayyorgarlik/','◎','Tanlovga tayyorgarlik'),('architecture','/arxitektura/','⌘','Loyiha arxitekturasi'),('workflow','/ish-tartibi/','↳','AI bilan ish tartibi'),('api','/api/','⇄','API va sinovlar'),('start','/design/start/','↗','AIga topshiriq'),('research','/ustoz/','≡','Tanlov materiallari'),('context','/ai/','⊞','AI konteksti'),('quality','/design/standart/','✓','Sifat mezonlari'),('keys','/keys/','◇','Kalitlar ombori')]
 links=''.join(f'<a href="{url}"'+(' aria-current="page"' if key==active else '')+f'><span aria-hidden="true">{icon}</span>{text}</a>' for key,url,icon,text in nav)
 size=(ROOT/'kit.zip').stat().st_size/1024/1024
 kit_version=sha256((ROOT/'kit.zip').read_bytes()).hexdigest()[:12]
 return f'''<!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Ustoz AI tanlovi uchun dizayn tanlash, haqiqiy kod va kontekst bilan ishni davom ettirish maydoni."><meta name="theme-color" content="{"#111216" if active=="library" else "#f7f7f4"}"><title>{escape(title)}</title><link rel="icon" href="/assets/hq/mark.svg?v=workspace"><link rel="preload" href="/assets/hq/fonts/sans.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="/assets/hq/workspace.css?v={css}"><link rel="stylesheet" href="/assets/hq/geometry.css?v={geometry}"><link rel="stylesheet" href="/assets/hq/aurora.css?v={aurora}">{extra}<script defer src="/assets/hq/site.js?v={js}"></script><script type="module" src="/assets/hq/workspace.js?v={module}"></script></head><body data-page="{active}"><a class="skip" href="#main">Asosiy mazmunga o‘tish</a><div class="workspace-shell"><aside class="workspace-sidebar"><a class="workspace-brand" href="/"><span class="brand-symbol" aria-hidden="true">a<span>.</span></span><span>Azizbek Safarov<small>Ochiq ish maydoni</small></span></a><p class="sidebar-label">KUTUBXONA VA VOSITALAR</p><button class="nav-toggle" id="nav-toggle" type="button" aria-expanded="false" aria-controls="workspace-nav" hidden>Bo‘limlar <span aria-hidden="true">☰</span></button><nav class="workspace-nav" id="workspace-nav" aria-label="Asosiy navigatsiya">{links}</nav><div class="sidebar-note"><span class="note-symbol" aria-hidden="true">↙</span><p>Yangi kompyuter.<br>Shu ishning davomi.</p><a href="/ai/">Kontekstni olib ketish →</a></div><a href="/design/kit.zip?v={kit_version}" class="offline-link" download data-download><span aria-hidden="true">↓</span><span>Oflayn paket<small>{size:.1f} MB · kod + kontekst</small></span></a><div class="sidebar-footer"><a href="https://github.com/AzizbekSafarov/azizbeksafarov.github.io">GitHub ↗</a><span>Mustaqil tayyorgarlik</span></div></aside><div class="workspace-body"><header class="workspace-top"><span>Azizbek / <b>{'Dizaynlar' if active=='library' else dict(preparation='Tanlovga tayyorgarlik',start='AIga topshiriq',context='AI konteksti',quality='Sifat mezonlari',architecture='Loyiha arxitekturasi',api='API va sinovlar',workflow='AI bilan ish tartibi').get(active,'Ish maydoni')}</b></span><a href="/ustoz/">Ustoz AI tanlovi <span aria-hidden="true">↗</span></a></header><main id="main">{content}</main><footer class="workspace-footer"><p>Mustaqil tayyorgarlik maydoni. Joydagi bilet va reglament ustuvor.</p><a href="/ai/">AI yo‘riqnomasi →</a><span id="global-download-status" role="status"></span></footer></div></div></body></html>'''

def build_library(catalog):
 content=library(catalog)
 content='<p class="context-explainer" style="margin:20px 28px;line-height:1.8"><strong>Tanlov konteksti yangilandi · 28-oktabr.</strong> <a href="/design/handoff/current-competition.md">Yangi portal, statistika va natija holati →</a>. Eski sanalar va shablon natijalar joriy fakt deb olinmaydi.</p>'+content
 # Keep real navigation actions above the preview, visible before scrolling.
 summary=re.search(r'<p id="selected-summary">.*?</p>',content).group()
 content=content.replace(summary,'',1)
 heading=re.search(r'<div class="selected-heading">.*?</a></div>',content).group()
 actions=re.search(r'<div class="selected-actions">.*?</div><div class="selected-resources">.*?</div>',content).group()
 status='<p class="download-status" id="download-status" role="status"></p>'
 content=content.replace(heading,'',1).replace(actions,'',1).replace(status,'',1).replace('<div class="preview-browser">',heading+summary+actions+status+'<div class="preview-browser">',1)
 for p in (SITE/'index.html',ROOT/'index.html'):p.write_text(frame('Dizayn kutubxonasi — Azizbek Safarov',content),encoding='utf-8',newline='\n')
 brief=(SITE/'ai.md').read_text(encoding='utf-8')
 contexts=''.join(f'<li><a href="/design/{t["slug"]}/">{escape(t["name"])}<span>Yo‘riqnoma + kod ↗</span></a></li>' for t in catalog)
 reader=f'''<div class="document-page"><p class="eyebrow">YANGI AI UCHUN BOSHLASH NUQTASI</p><h1>Ishning kontekstini<br>o‘zingiz bilan oling.</h1><p class="document-lead">Tanlangan dizaynning yo‘riqnomasini AIga bering. Unda haqiqiy kod, ishga tushirish, tanlov ma’lumoti va tekshiruv tartibi bor.</p><p><a href="/tayyorgarlik/">Tanlov oldidan siz va AI bajaradigan ishlar →</a></p><section class="context-copy"><label for="quick-prompt">Yangi chatga yuboriladigan matn</label><textarea id="quick-prompt" readonly rows="4">https://azizbeksafarov.github.io/ai.md
Tanlov kontekstini to‘liq o‘qi: /tayyorgarlik/full-context.md yoki reading-plan.json dagi aynan shu manbalar. START-HERE bilan cheklanma; o‘qilmagan qismini ayt. Faqat men tanlagan dizaynning to‘liq source ZIPini manifest bilan tekshir. Dizayn: [nom]. Bilet: [aynan matn]. Qolgan vaqt va joydagi qoidalar: [haqiqiy holat]. Men bilan o‘zbekcha ishlang.</textarea><div class="copy-line"><button class="button dark" type="button" data-copy="quick" data-status="quick-status">Matnni nusxalash ↗</button><a href="/ai.md" download data-download>Asl Markdown fayli ↓</a></div><p id="quick-status" class="copy-status" role="status"></p></section><h2>Qaysi dizayn bilan davom etamiz?</h2><ul class="context-list">{contexts}</ul><details class="full-context"><summary>To‘liq markaziy kontekstni o‘qish</summary><pre>{escape(brief)}</pre></details><p class="context-explainer">Havola AIga avtomatik xotira yoki fayl tahrirlash vositasini bermaydi. O‘qiy olmasa, Markdown fayli yoki kod ZIPini chatga bering.</p></div>'''
 reader=reader.replace('<section class="context-copy">','<p class="context-explainer"><a href="/ish-tartibi/">AI bilan ish tartibi: o‘qish yo‘li, ehtimoliy xatolar va topshirish shablonlari →</a></p><section class="context-copy">',1)
 folder=SITE/'ai';folder.mkdir(exist_ok=True);(folder/'index.html').write_text(frame('AI konteksti — Azizbek Safarov',reader,'context'),encoding='utf-8',newline='\n')
